import { test } from 'node:test';
import assert from 'assert';
import { statement } from '../src/statements.js';
import { createInvoice, issueInvoice, applyVoucher } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('statement: lists invoices for customer with status issued or partially_paid', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BASIC', qty: 2 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'BASIC', qty: 3 }],
  });
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value];
  const result = statement('C-001', invoices, '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.invoices.length, 2);
});

test('statement: filters out draft invoices', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BASIC', qty: 2 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'BASIC', qty: 3 }],
  });
  // inv2Result.value is still in draft status

  const invoices = [inv1Issued.value, inv2Result.value];
  const result = statement('C-001', invoices, '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].number, inv1Issued.value.number);
});

test('statement: filters out invoices with issueDate after asOf', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BASIC', qty: 2 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'BASIC', qty: 3 }],
  });
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value];
  const result = statement('C-001', invoices, '2026-10-10');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  assert.equal(result.value.invoices[0].issueDate, '2026-10-01');
});

test('statement: includes invoice fields (number, issueDate, dueDate, total, due)', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BASIC', qty: 2 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const invoices = [inv1Issued.value];
  const result = statement('C-001', invoices, '2026-10-31');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 1);
  const stmt = result.value.invoices[0];
  assert.equal(typeof stmt.number, 'string');
  assert.equal(typeof stmt.issueDate, 'string');
  assert.equal(typeof stmt.dueDate, 'string');
  assert.equal(typeof stmt.total, 'number');
  assert.equal(typeof stmt.due, 'number');
});

test('statement: calculates due (from balanceDue)', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BASIC', qty: 2 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const invoices = [inv1Issued.value];
  const result = statement('C-001', invoices, '2026-10-31');

  assert.equal(result.ok, true);
  const stmt = result.value.invoices[0];
  // BASIC is €50.00, qty 2, no discount = €100.00, VAT 21% = €21.00, total = €121.00 = 12100 cents
  assert.equal(stmt.total, 12100);
  assert.equal(stmt.due, 12100); // unpaid
});

test('statement: calculates totalDue as sum of all due amounts', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BASIC', qty: 2 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

  const inv2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-02',
    lines: [{ sku: 'BASIC', qty: 1 }],
  });
  const inv2Issued = issueInvoice(inv2Result.value, [inv1Issued.value.number]);

  const invoices = [inv1Issued.value, inv2Issued.value];
  const result = statement('C-001', invoices, '2026-10-31');

  assert.equal(result.ok, true);
  // inv1: €121.00 (12100), inv2: €60.50 (6050)
  assert.equal(result.value.totalDue, 18150);
});

test('statement: subtracts payments from due', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-01',
    lines: [{ sku: 'BASIC', qty: 2 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

  let inv1 = inv1Issued.value;
  const paymentResult = recordPayment(inv1, { amount: 6000, date: '2026-10-05' });
  inv1 = paymentResult.value;

  const invoices = [inv1];
  const result = statement('C-001', invoices, '2026-10-31');

  assert.equal(result.ok, true);
  const stmt = result.value.invoices[0];
  // Total €121.00 (12100), paid €60.00 (6000), due €61.00 (6100)
  assert.equal(stmt.total, 12100);
  assert.equal(stmt.due, 6100);
  assert.equal(result.value.totalDue, 6100);
});

test('statement: sorts invoices by issueDate ascending', () => {
  const inv1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-05',
    lines: [{ sku: 'BASIC', qty: 1 }],
  });
  const inv1Issued = issueInvoice(inv1Result.value, []);

